import{_ as e,o as t,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Agent 应用工程总览","description":"说明如何把 Agent、RAG 和工作流封装为具备服务、数据、缓存和后台任务能力的完整后端应用。","frontmatter":{"title":"Agent 应用工程总览","description":"说明如何把 Agent、RAG 和工作流封装为具备服务、数据、缓存和后台任务能力的完整后端应用。"},"headers":[],"relativePath":"py-agent/application/index.md","filePath":"py-agent/application/index.md","lastUpdated":1785380441000}'),l={name:"py-agent/application/index.md"};function o(r,a,p,d,s,c){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="agent-应用工程总览" tabindex="-1">Agent 应用工程总览 <a class="header-anchor" href="#agent-应用工程总览" aria-label="Permalink to &quot;Agent 应用工程总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本模块回答一个核心问题：怎样把已经能够运行的 Agent、RAG 或工作流，建设成可以被真实用户和其他系统稳定调用的后端应用。学习主线不按 FastAPI、PostgreSQL、Redis 等产品堆砌，而是按服务接口、数据持久化、缓存协调、后台执行和应用集成五类职责组织。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>完成本模块后，你应该能够：</p><ul><li>用 HTTP API、SSE 或实时连接暴露 Agent 能力；</li><li>区分业务数据、Agent State、Checkpoint、长期记忆、缓存和任务状态；</li><li>使用 PostgreSQL 管理业务数据、事务、并发和 Schema 迁移；</li><li>使用 Redis 处理缓存、过期、限流和分布式协调；</li><li>使用队列与 Worker 执行长任务，并处理重试、幂等、Outbox 和死信；</li><li>组织数据库、Redis、模型客户端和 Agent Runtime 的连接生命周期；</li><li>将这些能力组合为一个边界清楚、可测试的 Agent 后端服务。</li></ul><h2 id="主题分组" tabindex="-1">主题分组 <a class="header-anchor" href="#主题分组" aria-label="Permalink to &quot;主题分组&quot;">​</a></h2><ul><li><a href="/py-agent/application/services-api/">服务与接口</a></li><li><a href="/py-agent/application/data-persistence/">数据与持久化</a></li><li><a href="/py-agent/application/redis-coordination/">Redis 与协调</a></li><li><a href="/py-agent/application/background-tasks/">后台任务</a></li><li><a href="/py-agent/application/application-integration/">应用集成</a></li></ul><h2 id="内容边界" tabindex="-1">内容边界 <a class="header-anchor" href="#内容边界" aria-label="Permalink to &quot;内容边界&quot;">​</a></h2><p>Python 异步、HTTP 客户端、Pydantic 和配置基础属于“基础与模型”；Agent、工具和 Middleware 属于“Agent 开发”；Checkpoint 与 Durable Execution 的框架语义属于“工作流与多 Agent”。本模块只负责把这些能力接入应用服务和数据基础设施。</p><p>系统化测试、评测、安全治理、模型服务、可观测性和部署运维放在“质量与生产”；跨领域架构决策和综合业务项目放在“架构与实战”。本模块不会扩展成完整的 Web 后端、数据库管理或分布式系统百科。</p><h2 id="推荐顺序" tabindex="-1">推荐顺序 <a class="header-anchor" href="#推荐顺序" aria-label="Permalink to &quot;推荐顺序&quot;">​</a></h2><p>建议依次学习服务接口、数据持久化、Redis、后台任务和应用集成。只开发本地脚本时可以暂缓 PostgreSQL、Redis 和队列；一旦应用需要多用户、多进程、长任务或故障恢复，就应进入对应分组。</p>',13)])])}const u=e(l,[["render",o]]);export{g as __pageData,u as default};
